var obj1Input = input.get('object1');
var obj2Input = input.get('object2');
var obj3Input = input.get('object3') || '';
var conflictStrategy = input.get('conflictStrategy') || 'overwrite';
var arrayStrategy = input.get('arrayStrategy') || 'replace';

if (!obj1Input) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Object 1 is required');
    output.set('Result', '{}');
    tags.trigger('error');
} else {
    try {
        var obj1 = json.parse(obj1Input);
        var obj2 = obj2Input ? json.parse(obj2Input) : {};
        var obj3 = obj3Input ? json.parse(obj3Input) : null;

        var conflicts = [];

        function isObject(val) {
            return val !== null && typeof val === 'object' && !Array.isArray(val);
        }

        function deepMerge(target, source, path) {
            path = path || '';
            var result = {};

            var allKeys = {};
            var targetKeys = Object.keys(target);
            var sourceKeys = Object.keys(source);
            for (var i = 0; i < targetKeys.length; i++) allKeys[targetKeys[i]] = true;
            for (var i = 0; i < sourceKeys.length; i++) allKeys[sourceKeys[i]] = true;
            var keys = Object.keys(allKeys);

            for (var k = 0; k < keys.length; k++) {
                var key = keys[k];
                var currentPath = path ? path + '.' + key : key;
                var targetVal = target[key];
                var sourceVal = source[key];

                if (targetVal === undefined) {
                    result[key] = sourceVal;
                } else if (sourceVal === undefined) {
                    result[key] = targetVal;
                } else if (isObject(targetVal) && isObject(sourceVal)) {
                    result[key] = deepMerge(targetVal, sourceVal, currentPath);
                } else if (Array.isArray(targetVal) && Array.isArray(sourceVal)) {
                    conflicts.push({path: currentPath, target: targetVal, source: sourceVal, type: 'array'});
                    if (arrayStrategy === 'concat') {
                        result[key] = targetVal.concat(sourceVal);
                    } else if (arrayStrategy === 'unique') {
                        var combined = targetVal.concat(sourceVal);
                        var seen = {};
                        result[key] = combined.filter(function(item) {
                            var k = typeof item === 'object' ? json.stringify(item) : String(item);
                            if (seen[k]) return false;
                            seen[k] = true;
                            return true;
                        });
                    } else {
                        result[key] = sourceVal;
                    }
                } else {
                    conflicts.push({path: currentPath, target: targetVal, source: sourceVal, type: 'value'});
                    if (conflictStrategy === 'keepFirst') {
                        result[key] = targetVal;
                    } else if (conflictStrategy === 'preferNull') {
                        result[key] = sourceVal !== null ? sourceVal : targetVal;
                    } else {
                        result[key] = sourceVal;
                    }
                }
            }

            return result;
        }

        var merged = deepMerge(obj1, obj2, '');
        if (obj3) {
            merged = deepMerge(merged, obj3, '');
        }

        var mergedKeys = [];
        function collectKeys(obj, prefix) {
            var keys = Object.keys(obj);
            for (var i = 0; i < keys.length; i++) {
                var p = prefix ? prefix + '.' + keys[i] : keys[i];
                mergedKeys.push(p);
                if (isObject(obj[keys[i]])) {
                    collectKeys(obj[keys[i]], p);
                }
            }
        }
        collectKeys(merged, '');

        output.set('Result', json.stringify(merged));
        output.set('ResultObject', merged);
        output.set('ConflictCount', conflicts.length);
        output.set('Conflicts', json.stringify(conflicts));
        output.set('KeyCount', mergedKeys.length);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Merged objects: ' + mergedKeys.length + ' keys, ' + conflicts.length + ' conflicts');

        if (conflicts.length > 0) {
            tags.trigger('conflicts');
        }
        tags.trigger('success');

    } catch (ex) {
        log.error('Merge failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('Result', '{}');
        tags.trigger('error');
    }
}
